# ----------------------------------------------------------------------------------------
# Minimal DER reader (enough for X.509 certificates)
# ----------------------------------------------------------------------------------------


class DerError(ValueError):
    pass


def _tlv(buf, i, end):
    """Return (tag, value_start, value_end) for the TLV at buf[i]."""
    if i + 2 > end:
        raise DerError("truncated")
    tag = buf[i]
    if tag & 0x1F == 0x1F:
        raise DerError("high tag")
    b = buf[i + 1]
    if b < 0x80:
        ln, j = b, i + 2
    else:
        n = b & 0x7F
        if n == 0 or n > 4 or i + 2 + n > end:
            raise DerError("bad length")
        ln = int.from_bytes(bytes(buf[i + 2:i + 2 + n]), "big")
        j = i + 2 + n
    if j + ln > end:
        raise DerError("overrun")
    return tag, j, j + ln


def _children(buf, start, end):
    i = start
    while i < end:
        tag, vs, ve = _tlv(buf, i, end)
        yield tag, i, vs, ve
        i = ve


